/* Exploration polish. Saved discoveries use stable IDs; wildlife remains non-hostile. */
(()=>{'use strict';const T=THREE,W=EmberTerrain,D=SurvivalData,P=EmberWorld.prototype;
const oldStructure=P.structure;
P.structure=function(s){if(s.type!=='house')return oldStructure.call(this,s);const g=this.group(s.x,s.y,s.z,this.dynamic),m=(kind,color,x,y,z,a,b,c,tex)=>this.mesh(g,kind,color,x,y,z,a,b,c,false,tex);
 // Solid masonry plinth and thick timber walls close every face, including the gables.
 const bottom=Math.min(...[[-4,-3.5],[-4,3.5],[4,-3.5],[4,3.5]].map(([x,z])=>W.ground(s.x+x,s.z+z)-s.y))-.15;
 m('box','#8e9c99',0,bottom/2,0,8,-bottom+.3,7,'moss-stone');m('box','#8e7255',0,.22,0,8,.16,7,'timber');
 for(const x of[-3.7,3.7])for(const z of[-3.2,3.2])m('box','#68523f',x,2.14,z,.32,3.9,.32,'timber');
 if(s.progress>.25){m('box','#c7bba0',0,2.15,-3.16,7.7,3.7,.42,'timber');for(const x of[-3.68,3.68])m('box','#bbaa8b',x,2.15,0,.42,3.7,6.7,'timber');}
 if(s.progress>.55){for(const x of[-2.5,2.5])m('box','#bbaa8b',x,2.15,3.16,2.7,3.7,.42,'timber');m('box','#bbaa8b',0,3.7,3.16,2.35,.6,.42,'timber');for(const x of[-1.06,1.06])m('box','#68523f',x,1.75,3.4,.16,2.9,.18,'timber');m('box','#68523f',0,3.23,3.4,2.3,.16,.18,'timber');}
 if(s.progress>.8){for(const side of[-1,1]){const roof=m('box','#8a6f54',side*2.12,4.94,0,4.8,.32,8.2,'shingles');roof.rotation.z=-side*.49;}
 const shape=new T.Shape();shape.moveTo(-3.88,0);shape.lineTo(3.88,0);shape.lineTo(0,2.08);shape.closePath();const geometry=new T.ExtrudeGeometry(shape,{depth:.4,bevelEnabled:false,steps:1});for(const z of[-3.38,2.98]){const mesh=new T.Mesh(geometry,this.mat('#c7bba0',false,'timber'));mesh.position.set(0,4,z);mesh.castShadow=true;mesh.receiveShadow=true;g.add(mesh);}m('box','#68523f',0,5.99,0,.24,.26,8.2,'timber');
 for(const y of[.55,3.9]){m('box','#68523f',0,y,-3.4,8,.16,.16,'timber');for(const x of[-3.91,3.91])m('box','#68523f',x,y,0,.16,.16,7,'timber');}
 // Closed shutters are inset into decorative window frames; no holes or one-sided planes.
 for(const x of[-3.92,3.92]){m('box','#4b6869',x,2.35,-.5,.08,1.3,1.7,'timber');for(const z of[-1.4,.4])m('box','#68523f',x*1.005,2.35,z,.15,1.5,.12,'timber');m('box','#68523f',x,1.65,-.5,.3,.12,2,'timber');}
 }
 if(s.progress>=1){m('box','#68523f',2,.55,-1.35,2,.5,2.7,'timber');m('box','#738f8a',2,.88,-1.35,1.9,.2,2.65,'leather');m('box','#e1d5ba',2,1.03,-2.2,1.5,.18,.6,'leather');m('box','#94704b',-2.2,1.05,1,1.5,.16,1.25,'timber');for(const x of[-2.8,-1.6])for(const z of[.55,1.45])m('box','#68523f',x,.65,z,.12,.8,.12,'timber');m('box','#c7aa61',-2.2,1.35,1,.12,.45,.12,'brass');m('sphere','#ffe5ac',-2.2,1.61,1,.09,.14,.09);for(let i=0;i<3;i++)m('box',['#657968','#94704b','#c7aa61'][i],-2.2+i*.28,2.65,-2.85,.22,.45,.25,'leather');m('box','#68523f',-1.9,2.38,-2.85,2.7,.12,.6,'timber');}
 if(s.progress>.8){for(const x of[-3.91,3.91])for(const z of[-3.4,3.4])m('box','#68523f',x,2.14,z,.18,3.9,.18,'timber');for(const z of[-3.42,3.42]){m('box','#68523f',0,4,z,7.9,.18,.16,'timber');m('box','#68523f',0,5,z,.16,2.15,.16,'timber');for(const side of[-1,1]){const brace=m('box','#68523f',side*1.8,4.95,z,4.08,.13,.16,'timber');brace.rotation.z=-side*.48;}}for(const x of[-2.5,2.5]){const shutter=m('box','#426f66',x,2.25,3.41,1.15,1.25,.08);shutter.material=new T.MeshStandardMaterial({color:new T.Color('#5f7667').convertSRGBToLinear(),roughness:1});for(const dx of[-.64,.64])m('box','#68523f',x+dx,2.25,3.46,.1,1.5,.12,'timber');for(const y of[1.55,2.95])m('box','#68523f',x,y,3.46,1.4,.12,.15,'timber');m('box','#68523f',x,2.25,3.48,.08,1.3,.10,'timber');}}
 for(const o of g.children)if(o.isMesh&&o.scale.x===1.9&&o.scale.y===.2)o.material=new T.MeshStandardMaterial({color:new T.Color('#6b8b83').convertSRGBToLinear(),roughness:1});
 const plaster=new T.MeshStandardMaterial({color:new T.Color(['#d8c9ab','#c5cbb2','#c8b8a3'][Math.abs([...s.id].reduce((a,c)=>a+c.charCodeAt(0),0))%3]).convertSRGBToLinear(),roughness:1});for(const o of g.children)if(o.isMesh&&((o.scale.y===3.7)||(o.scale.y===.6&&o.position.y===3.7)||o.geometry.type==='ExtrudeGeometry'))o.material=plaster;
 return g;
};
function villager(world,g,merchant,variant){g.clear();const m=(kind,c,x,y,z,a,b,d)=>world.mesh(g,kind,c,x,y,z,a,b,d),skin=['#cfa17b','#a87858','#e0b895'][variant%3],cloth=merchant?'#426f66':['#86614f','#62768c','#718351'][variant%3];
 m('sphere',cloth,0,.96,0,.28,.43,.17);m('cylinder','#5d4834',0,.76,0,.29,.10,.18);m('sphere',skin,0,1.54,.015,.205,.25,.19);m('sphere','#4f392b',0,1.70,-.025,.215,.13,.19);m('sphere',skin,0,1.54,.205,.055,.065,.055);
 for(const side of[-1,1]){m('sphere',skin,side*.206,1.54,0,.045,.075,.045);m('sphere','#f5eddc',side*.075,1.60,.179,.046,.028,.018);m('sphere','#322b27',side*.075,1.60,.195,.018,.020,.009);m('box','#594235',side*.075,1.65,.184,.085,.018,.02);m('cylinder','#4e5352',side*.13,.36,0,.105,.62,.11);m('sphere','#4b392b',side*.13,.09,.065,.12,.10,.20);const arm=m('cylinder',cloth,side*.33,1.02,0,.11,.55,.11);arm.rotation.z=side*.12;m('sphere',skin,side*.365,.70,.025,.095,.13,.09);}
 m('box','#966c56',0,1.435,.19,.075,.016,.018);if(merchant){m('cylinder','#b79d64',0,1.82,0,.30,.045,.27);m('cylinder','#b79d64',0,1.91,0,.18,.18,.17);m('box','#aa925d',0,.76,.19,.09,.09,.03);}else m('box','#ccbd95',0,1.16,.175,.12,.35,.03);
}
const priorBuild=SurvivalExploration.build;
SurvivalExploration.build=function(world){priorBuild(world);world.villageTreasures=[];for(const [vi,entry]of world.villageGroups.entries()){const npcs=entry.group.children.filter(o=>o.isGroup&&o.children.some(c=>c.position.y===1.55));npcs.forEach((g,i)=>villager(world,g,i===0,vi+i));}
 for(const [n,s]of world.villageHouses.entries()){const id=s.id.replace('-house-','-treasure-'),p={id,x:s.x-2.35,y:s.y+.3,z:s.z-1.6,index:n};const g=world.group(p.x,p.y,p.z);const base=world.mesh(g,'box','#94704b',0,.42,0,1.35,.84,.85,false,'timber'),lid=world.group(0,.84,-.42,g);world.mesh(lid,'box','#94704b',0,.09,.42,1.4,.18,.91,false,'timber');for(const x of[-.45,.45]){world.mesh(g,'box','#c7aa61',x,.42,.44,.09,.84,.04,false,'brass');world.mesh(lid,'box','#c7aa61',x,.19,.42,.09,.025,.91,false,'brass');}world.mesh(g,'box','#c7aa61',0,.62,.46,.19,.19,.07,false,'brass');world.villageTreasures.push({...p,g,lid});world.explorationSolids.push({x:p.x,y:p.y+.42,z:p.z,sx:.675,sy:.42,sz:.425});}
};
function treasureTarget(state,world){const chest=world.villageTreasures.find(c=>Math.hypot(state.x-c.x,state.z-c.z)<2.5&&Math.abs(state.y-c.y)<1.5&&!state.openedVillageChests?.includes(c.id));return chest?{type:'villageTreasure',data:chest,label:'家の宝箱を開ける'}:null;}
function treasure(state,chest){D.upgradeKnowledge(state);if(state.openedVillageChests.includes(chest.id))return null;state.openedVillageChests.push(chest.id);const possibilities=['sword','chest','house','spear','bow','arrow','shield','axe','daggers','boomerang','bomb','jetpack','fuel','staff','gravity','stormblade'];const id=possibilities[chest.index%possibilities.length],learned=D.knows(state,id)?[]:[id];state.blueprints.push(...learned);const materials={ore:2+chest.index%3,berry:3};for(const [id,n]of Object.entries(materials))D.add(state.inventory,id,n);return{learned,materials};}
const skin=new T.MeshStandardMaterial({color:new T.Color('#b88864').convertSRGBToLinear(),roughness:.8}),sleeve=new T.MeshStandardMaterial({color:'#4c6960',roughness:.9}),handGeo=new T.SphereGeometry(1,12,8);
function addHand(world,parent,id){const g=new T.Group();g.userData.playerHand=true;const part=(mat,x,y,z,a,b,c)=>{const m=new T.Mesh(handGeo,mat);m.position.set(x,y,z);m.scale.set(a,b,c);m.castShadow=false;g.add(m);};part(sleeve,.15,-.40,.26,.13,.31,.13);part(skin,.06,-.14,.08,.115,.18,.09);for(let i=0;i<4;i++){part(skin,-.035+i*.048,-.08,.105,.029,.085,.055);part(skin,-.035+i*.048,-.025,.075,.030,.032,.055);}part(skin,-.075,-.12,.12,.045,.09,.045);if(['hammer','axe','spear'].includes(id))g.position.set(.18,.02,.08);if(['bow','boomerang'].includes(id))g.position.set(.06,.29,.08);parent.add(g);}
const previousItem=P.itemVisual;
P.itemVisual=function(id,held=false){if(held&&id==='daggers'){const pair=new T.Group();for(const side of[-1,1]){const blade=previousItem.call(this,'sword',true);blade.scale.setScalar(.62);blade.position.set(side<0?-.55:0,.02,0);pair.add(blade);}const left=new T.Group();left.position.set(-.55,-.08,0);addHand(this,left,null);pair.add(left);return pair;}if(!held||!['pickaxe','compass'].includes(id))return previousItem.call(this,id,held);const g=new T.Group();g.userData.artId=id;g.userData.gripAtOrigin=true;const m=(kind,c,x,y,z,a,b,d,tex)=>this.mesh(g,kind,c,x,y,z,a,b,d,false,tex);
 if(id==='compass'){const body=m('cylinder','#c4aa6e',0,.13,0,.22,.065,.22,'brass');body.material=body.material.clone();body.material.map=null;body.material.bumpMap=null;body.material.roughness=.4;const dial=m('cylinder','#eee7d4',0,.169,0,.19,.012,.19);const cv=document.createElement('canvas');cv.width=cv.height=256;const ctx=cv.getContext('2d');ctx.fillStyle='#f1ead4';ctx.fillRect(0,0,256,256);ctx.translate(128,128);ctx.fillStyle='#304c48';ctx.textAlign='center';ctx.textBaseline='middle';ctx.font='bold 28px serif';for(let i=0;i<4;i++){const a=i*Math.PI/2;ctx.fillText(['N','E','S','W'][i],Math.sin(a)*87,-Math.cos(a)*87);}ctx.strokeStyle='#71634b';for(let i=0;i<32;i++){const a=i*Math.PI/16;ctx.beginPath();ctx.moveTo(Math.sin(a)*108,Math.cos(a)*108);ctx.lineTo(Math.sin(a)*118,Math.cos(a)*118);ctx.stroke();}const tex=new T.CanvasTexture(cv);tex.encoding=T.sRGBEncoding;const face=new T.Mesh(new T.CircleGeometry(.19,48),new T.MeshStandardMaterial({map:tex,roughness:.8}));face.rotation.x=-Math.PI/2;face.position.y=.18;g.add(face);const needle=m('cone','#b84e3c',0,.19,-.055,.035,.15,.025);needle.userData.handLayer=2;needle.rotation.x=-Math.PI/2;g.rotation.x=.95;g.userData.compassNeedle=needle;return g;}
 m('cylinder','#704830',0,.20,0,.055,.8,.055,'timber');m('cylinder','#68523f',0,-.02,0,.065,.25,.065,'leather');if(id==='hammer'){m('box','#abc5cb',0,.62,0,.48,.23,.22,'forged-iron');m('box','#8a9294',-.25,.62,0,.08,.28,.27,'forged-iron');}else{const head=this.tube(g,[[-.43,.56,0],[-.25,.70,0],[0,.75,0],[.25,.70,0],[.45,.53,0]],.065,'#858881','moss-stone');m('cylinder','#68523f',0,.65,0,.075,.18,.075,'leather');}g.traverse(o=>{if(o.isMesh){o.material=o.material.clone();o.material.bumpMap=null;o.material.bumpScale=0;if(o.material.metalness>.1){o.material.map=null;o.material.emissiveMap=null;o.material.emissiveIntensity=0;o.material.color.set('#909ea4').convertSRGBToLinear();o.material.metalness=.3;o.material.roughness=.5;}}});g.rotation.z=.12;return g;};
function animalId(e){return 'wild-'+Math.round(e.chunk.userData.east)+'-'+Math.round(e.chunk.userData.north)+'-'+Math.round(e.east*100)+'-'+Math.round(e.north*100);}
function animalLoot(spec){const id=spec.id,plan=spec.plan;const bag={};if(plan==='insect'){bag.shell=2;bag.wing=1;}else if(/fish|salmon|trout|carp|shark|ray/.test(id)||plan==='fish'){bag.fish=2;bag.bone=1;}else if(plan==='bird'||/eagle|owl|duck|goose|penguin|parrot/.test(id)){bag.meat=1;bag.wing=3;}else{bag.meat=Math.max(1,Math.min(6,Math.ceil(spec.scale*2)));bag.hide=2;bag.bone=1;if(/deer|elk|moose|caribou|reindeer/.test(id))bag.antler=2;if(/wolf|fox|jackal|coyote|hyena|bear|lion|tiger|jaguar|crocodile|elephant|boar|walrus/.test(id))bag.fang=2;if(/turtle|tortoise|armadillo/.test(id))bag.shell=3;}return bag;}
function hunt(world,state,dir,it,damage,onDrop){if(!['sword','stormblade','spear','axe','daggers'].includes(it.kind))return false;world.nativeRoot.updateWorldMatrix(true,true);const ray=new T.Raycaster(new T.Vector3(state.x,state.y+1.4,state.z),dir,0,it.range);let target=null,dist=Infinity;for(const e of world.native.animals){if(e.hunted||!e.model.visible)continue;const center=e.model.getWorldPosition(new T.Vector3());center.y+=Math.max(.25,e.offset||.8);const v=center.clone().sub(ray.ray.origin),len=v.length();if(len>it.range+e.spec.scale*.8||v.normalize().dot(dir)<.65)continue;const hits=ray.intersectObject(e.model,true);if(hits.length&&hits[0].distance<dist){target=e;dist=hits[0].distance;}}
 if(!target)return false;target.huntFlash=state.time+.2;target.huntHP=(target.huntHP??Math.max(20,Math.min(140,target.spec.scale*42)))-damage;if(target.huntHP<=0){target.hunted=true;target.model.visible=false;target.shadow.visible=false;state.huntedAnimals||={};state.huntedAnimals[animalId(target)]=state.time+600;const p=target.model.getWorldPosition(new T.Vector3());onDrop({id:'hunt'+state.nextId++,x:p.x,y:W.floor(p.x,p.z,p.y),z:p.z,items:animalLoot(target.spec)});}return true;}
let soundSample=-1,soundAmount=0;
function waterSound(state){if(state.time-soundSample<.5&&state.time>=soundSample)return soundAmount;soundSample=state.time;let nearest=40;if(!W.inCave(state.x,state.z,state.y))for(let r=0;r<=32;r+=8)for(let a=0;a<8;a++){const x=state.x+Math.sin(a*Math.PI/4)*r,z=state.z+Math.cos(a*Math.PI/4)*r;if(W.ground(x,z)<W.water-.7)nearest=Math.min(nearest,r);}soundAmount=Math.max(0,1-nearest/28);return soundAmount;}
let compassHud;
function update(world,state,hand,ambient,sun,playing){if(!compassHud){compassHud=document.createElement('div');compassHud.id='compassHud';document.body.append(compassHud);}compassHud.hidden=!playing||state.hand!=='compass';if(!compassHud.hidden){const angle=((-state.yaw*180/Math.PI)%360+360)%360,dirs=['北 N','北東 NE','東 E','南東 SE','南 S','南西 SW','西 W','北西 NW'];const home=state.structures.filter(s=>s.type==='house'&&s.progress>=1).sort((a,b)=>Math.hypot(a.x-state.x,a.z-state.z)-Math.hypot(b.x-state.x,b.z-state.z))[0]||state.checkpoint;if(home){const bearing=(Math.atan2(home.x-state.x,-(home.z-state.z))*180/Math.PI+360)%360,relative=((bearing-angle+540)%360)-180;compassHud.innerHTML=dirs[Math.round(angle/45)%8]+' · '+Math.round(angle)+'°<br>⌂ '+(Math.abs(relative)<20?'前方':relative>0?'右':'左')+' '+Math.round(Math.hypot(home.x-state.x,home.z-state.z))+' m';}else compassHud.textContent=dirs[Math.round(angle/45)%8]+' · '+Math.round(angle)+'° ／ 家・焚き火 未登録';}
 hand.traverse(o=>{if(o.userData.compassNeedle){const n=o.userData.compassNeedle;n.quaternion.setFromUnitVectors(new T.Vector3(0,1,0),new T.Vector3(Math.sin(state.yaw),0,-Math.cos(state.yaw)));n.position.set(Math.sin(state.yaw)*.055,.19,-Math.cos(state.yaw)*.055);}if(o.isMesh){o.renderOrder=100+(o.userData.handLayer||0);o.material.depthTest=false;if(!o.material.transparent){o.material.transparent=true;o.material.needsUpdate=true;}}});
 const brightness=Math.min(1,Math.max(.16,ambient.intensity+sun.intensity*.18));hand.traverse(o=>{if(o.isMesh&&o.material?.isMeshBasicMaterial){o.material.color.setScalar(brightness);}});
 for(const e of world.native.animals){e.model.rotation.z=e.huntFlash>state.time?Math.sin(state.time*40)*.06:0;const dead=(state.huntedAnimals?.[animalId(e)]||0)>state.time;if(dead!==!!e.hunted){e.hunted=dead;e.huntHP=undefined;}}
 for(const c of world.villageTreasures||[]){c.g.visible=Math.hypot(state.x-c.x,state.z-c.z)<220;c.lid.rotation.x=state.openedVillageChests?.includes(c.id)?-1.1:0;}
}
window.SurvivalUpgrade={treasureTarget,treasure,addHand,hunt,animalLoot,animalId,waterSound,update};
})();
